def count_good_integers(num1: str, num2: str, min_sum: int, max_sum: int) -> int:
    """ Count the number of integers x such that num1 <= x <= num2 and 
    min_sum <= digit_sum(x) <= max_sum, where digit_sum(x) is the sum of digits of x.

    Return the count modulo 10^9 + 7.

    Args:
        num1: A numeric string representing the lower bound (1 <= num1 <= 10^22)
        num2: A numeric string representing the upper bound (num1 <= num2 <= 10^22)
        min_sum: The minimum allowed digit sum (1 <= min_sum <= 400)
        max_sum: The maximum allowed digit sum (min_sum <= max_sum <= 400)

    Returns:
        The number of good integers modulo 10^9 + 7

    >>> count_good_integers("1", "12", 1, 8)
    11
    >>> count_good_integers("1", "5", 1, 5)
    5
    """
    MOD = 10**9 + 7

    def digit_sum(n: str) -> int:
        sum_digits = 0
        for digit in n:
            sum_digits += int(digit)
        return sum_digits

    def count_valid(num: str, min_sum: int, max_sum: int) -> int:
        n = len(num)
        dp = {}

        def solve(index: int, current_sum: int, is_tight: bool) -> int:
            if index == n:
                if min_sum <= current_sum <= max_sum:
                    return 1
                else:
                    return 0

            if (index, current_sum, is_tight) in dp:
                return dp[(index, current_sum, is_tight)]

            upper_limit = int(num[index]) if is_tight else 9
            count = 0

            for digit in range(upper_limit + 1):
                new_sum = current_sum + digit
                new_is_tight = is_tight and (digit == upper_limit)
                if new_sum <= max_sum:
                    count = (count + solve(index + 1, new_sum, new_is_tight)) % MOD

            dp[(index, current_sum, is_tight)] = count
            return count

        return solve(0, 0, True)

    count2 = count_valid(num2, min_sum, max_sum)
    count1 = count_valid(num1, min_sum, max_sum)

    if int(num1) == int(num2):
        if min_sum <= digit_sum(num1) <= max_sum:
            return 1
        else:
            return 0

    return (count2 - count1 + MOD) % MOD
```

